'use strict';
// Draft generated by FreeLLMAPI (gpt-oss-20b via ovh); saved by Claude.
// "FIX" comments mark the places where the generated draft crashed, leaked data, or was wrong.
const { pool, withTransaction } = require('../config/db');
const AppError = require('../utils/AppError');

const notify = (client, userId, actorId, type) => client.query(
  `INSERT INTO notifications (user_id, actor_id, type) VALUES ($1, $2, $3)`, [userId, actorId, type]);

async function isBlockedEitherWay(a, b) {
  const r = await pool.query(
    `SELECT 1 FROM blocks WHERE (blocker_id = $1 AND blocked_id = $2) OR (blocker_id = $2 AND blocked_id = $1) LIMIT 1`,
    [a, b]);
  return r.rowCount > 0;
}

async function followUser(followerId, targetUserId) {
  if (followerId === targetUserId) throw new AppError(400, 'You cannot follow yourself', 'SELF_FOLLOW');

  const targetResult = await pool.query(
    `SELECT id, is_private FROM users WHERE id = $1 AND status = 'active'`, [targetUserId]);
  if (!targetResult.rowCount) throw new AppError(404, 'User not found', 'USER_NOT_FOUND');
  if (await isBlockedEitherWay(followerId, targetUserId)) throw new AppError(404, 'User not found', 'USER_NOT_FOUND');

  if (!targetResult.rows[0].is_private) {
    return withTransaction(async (client) => {
      const followRes = await client.query(
        `INSERT INTO follows (follower_id, following_id) VALUES ($1, $2) ON CONFLICT DO NOTHING RETURNING follower_id`,
        [followerId, targetUserId]);
      if (followRes.rowCount) await notify(client, targetUserId, followerId, 'follow');
      return { status: 'following' };
    });
  }

  const existing = await pool.query(
    'SELECT 1 FROM follows WHERE follower_id = $1 AND following_id = $2', [followerId, targetUserId]);
  if (existing.rowCount) return { status: 'following' };

  return withTransaction(async (client) => {
    // FIX: the draft did a plain INSERT that threw a unique violation (HTTP 500) when a pending/accepted
    // request already existed. Upsert: only 'rejected'/'accepted' rows are reset to 'pending'; an already
    // pending request returns no row, so no duplicate notification is created.
    const reqRes = await client.query(
      `INSERT INTO follow_requests (requester_id, target_id, status) VALUES ($1, $2, 'pending')
       ON CONFLICT (requester_id, target_id) DO UPDATE SET status = 'pending', updated_at = NOW()
         WHERE follow_requests.status <> 'pending'
       RETURNING requester_id`, [followerId, targetUserId]);
    if (reqRes.rowCount) await notify(client, targetUserId, followerId, 'follow_request');
    return { status: 'requested' };
  });
}

async function unfollowUser(followerId, targetUserId) {
  return withTransaction(async (client) => {
    await client.query('DELETE FROM follows WHERE follower_id = $1 AND following_id = $2', [followerId, targetUserId]);
    await client.query(
      `DELETE FROM follow_requests WHERE requester_id = $1 AND target_id = $2 AND status = 'pending'`,
      [followerId, targetUserId]);
    return { status: 'none' };
  });
}

async function listIncomingRequests(userId, limit, cursor) {
  const params = [userId, limit + 1];
  let cursorCondition = '';
  if (cursor) { cursorCondition = 'AND fr.created_at < $3'; params.push(cursor); }
  const res = await pool.query(`
    SELECT fr.requester_id AS id, u.username, u.display_name AS "displayName",
           u.avatar_url AS "avatarUrl", fr.created_at AS "createdAt"
      FROM follow_requests fr
      JOIN users u ON fr.requester_id = u.id
     WHERE fr.target_id = $1 AND fr.status = 'pending' AND u.status = 'active'
       AND NOT EXISTS (SELECT 1 FROM blocks b
            WHERE (b.blocker_id = $1 AND b.blocked_id = u.id) OR (b.blocker_id = u.id AND b.blocked_id = $1))
       ${cursorCondition}
     ORDER BY fr.created_at DESC
     LIMIT $2`, params);
  return page(res.rows, limit, 'createdAt');
}

function page(rows, limit, tsKey) {
  let items = rows.map((r) => ({ ...r, [tsKey]: new Date(r[tsKey]).toISOString() }));
  let nextCursor = null;
  if (items.length > limit) {
    items = items.slice(0, limit);
    nextCursor = items[limit - 1][tsKey];
  }
  return { items, nextCursor };
}

async function respondToRequest(userId, requesterId, action) {
  const status = action === 'accept' ? 'accepted' : 'rejected';
  return withTransaction(async (client) => {
    // FIX: single guarded UPDATE inside the transaction (draft checked first, then updated = race window).
    const upd = await client.query(
      `UPDATE follow_requests SET status = $1, updated_at = NOW()
        WHERE requester_id = $2 AND target_id = $3 AND status = 'pending' RETURNING requester_id`,
      [status, requesterId, userId]);
    if (!upd.rowCount) throw new AppError(404, 'Follow request not found', 'NOT_FOUND');

    if (action === 'accept') {
      await client.query(
        'INSERT INTO follows (follower_id, following_id) VALUES ($1, $2) ON CONFLICT DO NOTHING', [requesterId, userId]);
      await notify(client, requesterId, userId, 'follow_accepted');
    }
    return { status };
  });
}

async function resolveListTarget(viewerId, username) {
  const res = await pool.query(
    `SELECT id, is_private FROM users WHERE username = $1 AND status = 'active'`, [username]);
  if (!res.rowCount) throw new AppError(404, 'User not found', 'USER_NOT_FOUND');
  const target = res.rows[0];

  if (viewerId !== target.id) {
    if (viewerId && (await isBlockedEitherWay(viewerId, target.id))) {
      throw new AppError(404, 'User not found', 'USER_NOT_FOUND');
    }
    if (target.is_private) {
      // FIX: the draft skipped this check entirely for anonymous viewers (private lists were public).
      let allowed = false;
      if (viewerId) {
        const f = await pool.query('SELECT 1 FROM follows WHERE follower_id = $1 AND following_id = $2', [viewerId, target.id]);
        allowed = f.rowCount > 0;
      }
      if (!allowed) throw new AppError(403, 'This account is private', 'PRIVATE_ACCOUNT');
    }
  }
  return target;
}

// side: 'followers' => rows where follows.following_id = target; 'following' => rows where follower_id = target
async function listConnections(side, viewerId, username, limit, cursor) {
  const target = await resolveListTarget(viewerId, username);
  const [ownCol, otherCol] = side === 'followers' ? ['following_id', 'follower_id'] : ['follower_id', 'following_id'];

  const params = [target.id, limit + 1];
  let sql = `
    SELECT f.${otherCol} AS id, u.username, u.display_name AS "displayName", u.avatar_url AS "avatarUrl",
           u.is_verified_creator AS "isVerifiedCreator", f.created_at AS "followedAt"
      FROM follows f
      JOIN users u ON u.id = f.${otherCol}
     WHERE f.${ownCol} = $1 AND u.status = 'active'`;
  if (cursor) { params.push(cursor); sql += ` AND f.created_at < $${params.length}`; }
  if (viewerId) {
    // FIX (added): hide users who are in a block relation with the viewer.
    params.push(viewerId);
    sql += ` AND NOT EXISTS (SELECT 1 FROM blocks b
              WHERE (b.blocker_id = $${params.length} AND b.blocked_id = u.id)
                 OR (b.blocker_id = u.id AND b.blocked_id = $${params.length}))`;
  }
  sql += ' ORDER BY f.created_at DESC LIMIT $2';

  const res = await pool.query(sql, params);
  return page(res.rows, limit, 'followedAt');
}

const listFollowers = (viewerId, username, limit, cursor) => listConnections('followers', viewerId, username, limit, cursor);
const listFollowing = (viewerId, username, limit, cursor) => listConnections('following', viewerId, username, limit, cursor);

async function removeFollower(userId, followerId) {
  await pool.query('DELETE FROM follows WHERE follower_id = $1 AND following_id = $2', [followerId, userId]);
  return { removed: true };
}

module.exports = { followUser, unfollowUser, listIncomingRequests, respondToRequest, listFollowers, listFollowing, removeFollower };
